llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Levofloxacin, a fluoroquinolone sharing the 4-oxo-quinoline-3-carboxylic acid core, has an absolute oral bioavailability approaching 100% in healthy volunteers, strongly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Trovafloxacin, another fluoroquinolone, has a mean absolute oral bioavailability of 87.6% in healthy volunteers, directly supporting high oral bioavailability for this quinolone chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "S/GSK1349572, a closely related 4-quinolone-3-carboxylic acid derivative with an N-alkyl substituent and methoxy group, has good oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Cilomilast has a mean absolute oral bioavailability of 96% (range 92–102%) in healthy volunteers, providing additional high-transfer evidence for nearly complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Encainide shows low oral bioavailability (30 ± 7%) in normal subjects, but this reflects extensive first-pass metabolism in a structurally unrelated antiarrhythmic and is not applicable to the quinolone carboxylic acid scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fluoroquinolone-3-carboxylic acid. Multiple high-transfer quinolone and quinolone-like analogues show high absolute oral bioavailability (approximately 88–100%), while the only low-bioavailability analogue is structurally unrelated and its low F is mechanism-specific first-pass metabolism. Thus F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "The unusual C-7 fluoro-aminomethylidene substituent is not directly represented in the available quinolone bioavailability records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

